draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#964B00';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-100, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-80);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2-30, H/2-40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2+30, H/2-40);
  ctx.stroke();

  // Draw wisdom lightbulb
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2-80, H/2-150, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-80, H/2-130);
  ctx.lineTo(W/2-80, H/2-110);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2-80, H/2-150, 20+10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // Draw lesson text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson ' + Math.floor(1 + 1157*Math.sin(t)), W/2, H/2+50);

  ctx.restore();
}
